# 23.11.: Box WLAN-Infos (Reihenfolge Media, XVII, Optimus Prime, sonst Hotspot 5 GHz)
touch /tmp/claude_remote
B=$(adb devices | awk '/:5555[[:space:]]+device/{print $1; exit}'); echo "Box $B"
adb -s $B shell 'getprop ro.build.version.release; getprop ro.build.version.sdk; id; cmd wifi status 2>&1 | head -8; echo "== gespeichert"; cmd wifi list-networks 2>&1 | head -20; echo "== scan"; cmd wifi start-scan; sleep 4; cmd wifi list-scan-results 2>&1 | grep -E "Media|XVII|Optimus|SSID" | head -15; echo "== help"; cmd wifi help 2>&1 | grep -E "^  (connect-network|list-networks|forget|start-softap|set-network|enable|disable|start-scan|settings-reset|network-requests|add-network)" ; echo "== store"; ls -l /data/misc/apexdata/com.android.wifi/WifiConfigStore.xml /data/misc/wifi/WifiConfigStore.xml 2>&1; grep -c "<Network>" /data/misc/apexdata/com.android.wifi/WifiConfigStore.xml /data/misc/wifi/WifiConfigStore.xml 2>&1; grep -o "<string name=\"SSID\">[^<]*" /data/misc/apexdata/com.android.wifi/WifiConfigStore.xml /data/misc/wifi/WifiConfigStore.xml 2>/dev/null; grep -c PreSharedKey /data/misc/apexdata/com.android.wifi/WifiConfigStore.xml /data/misc/wifi/WifiConfigStore.xml 2>/dev/null; echo "== softap"; grep -o "<string name=\"SSID\">[^<]*\|<int name=\"Band\" value=\"[0-9]*\|<int name=\"ApBand\" value=\"[0-9]*" /data/misc/apexdata/com.android.wifi/WifiConfigStoreSoftAp.xml /data/misc/wifi/softap.conf 2>/dev/null'
